read_csv:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.csv' (HEADER, DELIMITER ',');

SELECT * FROM read_csv('harvest.csv', header := true);

read_csv_auto:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.csv' (HEADER, DELIMITER ',');

SELECT * FROM read_csv_auto('harvest.csv');

read_json:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.json' (FORMAT JSON);

SELECT * FROM read_json('harvest.json');

read_json_auto:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.json' (FORMAT JSON);

SELECT * FROM read_json_auto('harvest.json');

read_parquet:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.parquet' (FORMAT PARQUET);

SELECT * FROM read_parquet('harvest.parquet');

parquet_scan:
COPY (SELECT 'apples' AS fruit, 12 AS quantity)
TO 'harvest.parquet' (FORMAT PARQUET);

SELECT * FROM parquet_scan('harvest.parquet');

json_group_object:
SELECT json_group_object(fruit, quantity) AS harvest
FROM (VALUES ('apples', 12), ('pears', 8))
  AS data(fruit, quantity);

last_value:
SELECT fruit, last_value(fruit) OVER (
  ORDER BY quantity DESC
  ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
) AS last_fruit
FROM (VALUES ('apples', 12), ('pears', 8)) AS data(fruit, quantity);

currval:
CREATE OR REPLACE SEQUENCE example_sequence START 1;
SELECT nextval('example_sequence');
SELECT currval('example_sequence') AS current_id;

arg_max_nulls_last:
SELECT arg_max_nulls_last(fruit, quantity, 2) AS fruit
FROM (VALUES ('apples', 12), ('pears', 8), ('plums', NULL))
  AS harvest(fruit, quantity);

arg_min_nulls_last:
SELECT arg_min_nulls_last(fruit, quantity, 2) AS fruit
FROM (VALUES ('apples', 12), ('pears', 8), ('plums', NULL))
  AS harvest(fruit, quantity);
